@IsTest
private class OpportunityWonHandlerTest {
    private static Integer seq = 0;

    private static Account newAccount(String rating) {
        seq++;
        return new Account(Name = 'Test Account ' + seq, Rating = rating);
    }

    private static Account createAccount(String rating) {
        Account a = newAccount(rating);
        insert a;
        return a;
    }

    private static Opportunity newOpp(Id accountId, String stage, Date closeDate, String nextStep) {
        seq++;
        return new Opportunity(
            Name = 'Test Opportunity ' + seq,
            AccountId = accountId,
            StageName = stage,
            CloseDate = closeDate,
            NextStep = nextStep
        );
    }

    private static Opportunity fetchOpp(Id oppId) {
        return [
            SELECT Id, Name, AccountId, StageName, NextStep, CloseDate, OwnerId
            FROM Opportunity
            WHERE Id = :oppId
            LIMIT 1
        ];
    }

    private static Account fetchAccount(Id accountId) {
        return [
            SELECT Id, Name, Rating, SystemModstamp
            FROM Account
            WHERE Id = :accountId
            LIMIT 1
        ];
    }

    private static List<Task> fetchTasks(Id oppId) {
        return [
            SELECT Id, Subject, WhatId, OwnerId, ActivityDate, Priority
            FROM Task
            WHERE WhatId = :oppId
        ];
    }

    private static Map<Id, List<Task>> fetchTasksByOpp(Set<Id> oppIds) {
        Map<Id, List<Task>> result = new Map<Id, List<Task>>();
        for (Id oppId : oppIds) {
            result.put(oppId, new List<Task>());
        }
        for (Task t : [
            SELECT Id, Subject, WhatId, OwnerId, ActivityDate, Priority
            FROM Task
            WHERE WhatId IN :oppIds
        ]) {
            result.get(t.WhatId).add(t);
        }
        return result;
    }

    private static void assertText(String expected, String actual, String message) {
        System.assertEquals(expected, actual, message);
        System.assert(
            expected == null ? actual == null : expected.equals(actual),
            message + ' (case-sensitive check) Expected: ' + expected + ', Actual: ' + actual
        );
    }

    private static void assertTask(Task t, Id oppId, Id ownerId, Date expectedDate) {
        System.assertNotEquals(null, t, 'Expected a Task to exist');
        assertText('Customer kick-off', t.Subject, 'Task Subject is wrong');
        System.assertEquals(oppId, t.WhatId, 'Task WhatId must be the Opportunity');
        System.assertEquals(ownerId, t.OwnerId, 'Task OwnerId must be the Opportunity owner');
        System.assertEquals(expectedDate, t.ActivityDate, 'Task ActivityDate must be CloseDate + 7 days');
        assertText('High', t.Priority, 'Task Priority is wrong');
    }

    private static Task assertSingleTask(Id oppId, Id ownerId, Date expectedDate) {
        List<Task> tasks = fetchTasks(oppId);
        System.assertEquals(1, tasks.size(), 'Expected exactly one Task for Opportunity ' + oppId);
        assertTask(tasks[0], oppId, ownerId, expectedDate);
        return tasks[0];
    }

    private static void assertNoTasks(Id oppId) {
        System.assertEquals(0, fetchTasks(oppId).size(), 'Expected no Tasks for Opportunity ' + oppId);
    }

    private static void assertBulkHandedOver(List<Opportunity> opps) {
        Set<Id> oppIds = new Set<Id>();
        Set<Id> accountIds = new Set<Id>();
        for (Opportunity o : opps) {
            oppIds.add(o.Id);
            if (o.AccountId != null) {
                accountIds.add(o.AccountId);
            }
        }
        Map<Id, Opportunity> fetched = new Map<Id, Opportunity>([
            SELECT Id, AccountId, StageName, NextStep, CloseDate, OwnerId
            FROM Opportunity
            WHERE Id IN :oppIds
        ]);
        System.assertEquals(opps.size(), fetched.size(), 'Unexpected number of Opportunities fetched');

        Map<Id, List<Task>> tasksByOpp = fetchTasksByOpp(oppIds);
        Integer totalTasks = 0;
        for (Id oppId : oppIds) {
            Opportunity o = fetched.get(oppId);
            assertText('Closed Won', o.StageName, 'Bulk Opportunity should be Closed Won');
            assertText(
                'Handover to Customer Success',
                o.NextStep,
                'Bulk Opportunity NextStep is wrong for ' + oppId
            );
            List<Task> tasks = tasksByOpp.get(oppId);
            System.assertEquals(1, tasks.size(), 'Bulk Opportunity must have exactly one Task: ' + oppId);
            assertTask(tasks[0], o.Id, o.OwnerId, o.CloseDate.addDays(7));
            totalTasks += tasks.size();
        }
        System.assertEquals(opps.size(), totalTasks, 'Bulk Task count is wrong');

        List<Account> accounts = [
            SELECT Id, Rating
            FROM Account
            WHERE Id IN :accountIds
        ];
        System.assertEquals(accountIds.size(), accounts.size(), 'Unexpected number of Accounts fetched');
        for (Account a : accounts) {
            assertText('Hot', a.Rating, 'Bulk Account Rating must be Hot for ' + a.Id);
        }
    }

    @IsTest
    private static void insertWonSetsNextStepCreatesExactTaskAndHeatsAccount() {
        Account acct = createAccount('Cold');
        Account unrelated = createAccount('Cold');
        Opportunity opp = newOpp(acct.Id, 'Closed Won', Date.newInstance(2030, 5, 10), 'Do not keep');

        insert opp;

        Opportunity fetched = fetchOpp(opp.Id);
        assertText('Handover to Customer Success', fetched.NextStep, 'Won insert must set NextStep');
        assertSingleTask(opp.Id, fetched.OwnerId, Date.newInstance(2030, 5, 17));
        assertText('Hot', fetchAccount(acct.Id).Rating, 'Won insert must heat its Account');
        assertText('Cold', fetchAccount(unrelated.Id).Rating, 'Unrelated Account must not be heated');
    }

    @IsTest
    private static void insertWonWithoutAccountStillHandovers() {
        Opportunity opp = newOpp(null, 'Closed Won', Date.newInstance(2029, 12, 25), null);

        insert opp;

        Opportunity fetched = fetchOpp(opp.Id);
        System.assertEquals(null, fetched.AccountId, 'Test Opportunity should have no Account');
        assertText('Handover to Customer Success', fetched.NextStep, 'Won insert without Account must set NextStep');
        assertSingleTask(opp.Id, fetched.OwnerId, Date.newInstance(2030, 1, 1));
    }

    @IsTest
    private static void insertWonWithAlreadyHotAccountDoesNotUpdateAccount() {
        Account acct = createAccount('Hot');
        Account beforeAcct = fetchAccount(acct.Id);
        Opportunity opp = newOpp(acct.Id, 'Closed Won', Date.newInstance(2030, 3, 10), null);

        Test.startTest();
        Integer rowsBefore = Limits.getDMLRows();
        Integer statementsBefore = Limits.getDMLStatements();
        insert opp;
        Integer rowsUsed = Limits.getDMLRows() - rowsBefore;
        Integer statementsUsed = Limits.getDMLStatements() - statementsBefore;
        Test.stopTest();

        System.assertEquals(2, rowsUsed, 'Only Opportunity and Task rows should be written; Hot Account must not be updated');
        System.assertEquals(2, statementsUsed, 'Only Opportunity and Task DML statements should occur; Hot Account must not be updated');

        Account afterAcct = fetchAccount(acct.Id);
        assertText('Hot', afterAcct.Rating, 'Already Hot Account must stay Hot');
        System.assertEquals(beforeAcct.SystemModstamp, afterAcct.SystemModstamp, 'Already Hot Account must not be updated');
        assertSingleTask(opp.Id, fetchOpp(opp.Id).OwnerId, Date.newInstance(2030, 3, 17));
    }

    @IsTest
    private static void insertNonWonStagesDoNothing() {
        Account a1 = createAccount('Cold');
        Account a2 = createAccount('Warm');
        Account a3 = createAccount(null);

        Opportunity prospecting = newOpp(a1.Id, 'Prospecting', Date.newInstance(2030, 1, 10), 'Qualify lead');
        Opportunity qualification = newOpp(a2.Id, 'Qualification', Date.newInstance(2030, 1, 11), null);
        Opportunity closedLost = newOpp(a3.Id, 'Closed Lost', Date.newInstance(2030, 1, 12), 'Lost - keep');

        insert new List<Opportunity>{ prospecting, qualification, closedLost };

        assertText('Qualify lead', fetchOpp(prospecting.Id).NextStep, 'Non-won NextStep must be preserved');
        System.assertEquals(null, fetchOpp(qualification.Id).NextStep, 'Non-won null NextStep must stay null');
        assertText('Lost - keep', fetchOpp(closedLost.Id).NextStep, 'Closed Lost NextStep must be preserved');

        assertNoTasks(prospecting.Id);
        assertNoTasks(qualification.Id);
        assertNoTasks(closedLost.Id);

        assertText('Cold', fetchAccount(a1.Id).Rating, 'Non-won Account must not be heated');
        assertText('Warm', fetchAccount(a2.Id).Rating, 'Non-won Account must not be heated');
        System.assertEquals(null, fetchAccount(a3.Id).Rating, 'Closed Lost Account Rating must stay null');
    }

    @IsTest
    private static void updateToWonFromOtherStagesHandovers() {
        Account a1 = createAccount('Cold');
        Account oldAccount = createAccount('Cold');
        Account newAccount = createAccount('Cold');

        Opportunity fromProspecting = newOpp(a1.Id, 'Prospecting', Date.newInstance(2030, 1, 1), 'Working it');
        Opportunity fromClosedLost = newOpp(oldAccount.Id, 'Closed Lost', Date.newInstance(2030, 4, 15), 'Was lost');
        insert new List<Opportunity>{ fromProspecting, fromClosedLost };
        assertNoTasks(fromProspecting.Id);
        assertNoTasks(fromClosedLost.Id);

        Opportunity p = fetchOpp(fromProspecting.Id);
        p.StageName = 'Closed Won';
        p.CloseDate = Date.newInstance(2030, 2, 10);
        p.NextStep = 'Attempted override';
        update p;

        Opportunity l = fetchOpp(fromClosedLost.Id);
        l.StageName = 'Closed Won';
        l.AccountId = newAccount.Id;
        update l;

        Opportunity fetchedP = fetchOpp(fromProspecting.Id);
        assertText('Handover to Customer Success', fetchedP.NextStep, 'Update to Won must set NextStep');
