/**
 * Keeps Account.FB_Open_Pipeline__c and Account.FB_Open_Opportunities__c
 * synchronised with the account's open opportunities.
 *
 * Deliberately uses no static run-once / already-processed guard: such a
 * guard would incorrectly skip a second, genuine Opportunity DML for the
 * same accounts later in the same transaction.
 *
 * Recursion with the legacy AccountTrigger is instead terminated by
 * recalculating from the database on every invocation and only updating
 * an Account when a calculated total actually differs from the stored
 * value. The AccountTrigger's follow-up Opportunity update (which only
 * changes FB_Account_Rating__c) therefore recalculates the same totals,
 * performs no Account DML, and the chain ends. A later genuine change
 * to Amount, IsClosed/StageName or AccountId calculates different
 * totals, so it is still applied.
 */
public inherited sharing class OpportunityPipelineHandler {

    public static void handle(
        List<Opportunity> newOpportunities,
        Map<Id, Opportunity> oldOpportunitiesById
    ) {
        Set<Id> accountIds = new Set<Id>();

        // Insert / update / undelete: the account(s) the record now belongs to.
        if (newOpportunities != null) {
            for (Opportunity opportunity : newOpportunities) {
                if (opportunity.AccountId != null) {
                    accountIds.add(opportunity.AccountId);
                }
            }
        }

        // Delete: the account it belonged to. Update: also the previous
        // account, so reparenting recalculates both the source and the
        // target account (as well as open/closed and amount changes).
        if (oldOpportunitiesById != null) {
            for (Opportunity opportunity : oldOpportunitiesById.values()) {
                if (opportunity.AccountId != null) {
                    accountIds.add(opportunity.AccountId);
                }
            }
        }

        if (accountIds.isEmpty()) {
            return;
        }

        recalculateAccounts(accountIds);
    }

    private static void recalculateAccounts(Set<Id> accountIds) {
        Map<Id, Decimal> pipelineByAccountId = new Map<Id, Decimal>();
        Map<Id, Decimal> countByAccountId = new Map<Id, Decimal>();

        // One bulk aggregate query. SUM ignores null Amounts; an account
        // whose open opportunities all have blank Amounts returns a null
        // SUM, which toDecimal converts to 0, while COUNT(Id) still
        // counts those opportunities.
        for (AggregateResult result : [
            SELECT AccountId, SUM(Amount) totalAmount, COUNT(Id) openCount
            FROM Opportunity
            WHERE AccountId IN :accountIds AND IsClosed = false
            GROUP BY AccountId
        ]) {
            Id accountId = (Id) result.get('AccountId');
            pipelineByAccountId.put(accountId, toDecimal(result.get('totalAmount')));
            countByAccountId.put(accountId, toDecimal(result.get('openCount')));
        }

        List<Account> accountsToUpdate = new List<Account>();

        for (Account account : [
            SELECT Id, FB_Open_Pipeline__c, FB_Open_Opportunities__c
            FROM Account
            WHERE Id IN :accountIds
        ]) {
            // Accounts with no remaining open opportunities have no
            // aggregate row, so they default to 0 / 0 rather than blank.
            Decimal newPipeline = pipelineByAccountId.containsKey(account.Id)
                ? pipelineByAccountId.get(account.Id)
                : 0;
            Decimal newCount = countByAccountId.containsKey(account.Id)
                ? countByAccountId.get(account.Id)
                : 0;

            // Only write when a total actually changed. In addition to
            // avoiding unnecessary DML, this is what stops the
            // Account -> Opportunity -> Account chain from recursing.
            if (
                isDifferent(account.FB_Open_Pipeline__c, newPipeline) ||
                isDifferent(account.FB_Open_Opportunities__c, newCount)
            ) {
                Account accountToUpdate = new Account(Id = account.Id);
                accountToUpdate.FB_Open_Pipeline__c = newPipeline;
                accountToUpdate.FB_Open_Opportunities__c = newCount;
                accountsToUpdate.add(accountToUpdate);
            }
        }

        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate;
        }
    }

    private static Boolean isDifferent(Decimal storedValue, Decimal calculatedValue) {
        // Apex Decimal has no visible compareTo method. The < and >
        // operators compare by value (ignoring scale), so this is a
        // scale-insensitive inequality check, unlike an equals check
        // that could be affected by differing decimal places.
        return storedValue == null
            || storedValue < calculatedValue
            || storedValue > calculatedValue;
    }

    private static Decimal toDecimal(Object value) {
        if (value == null) {
            return 0;
        }
        if (value instanceof Decimal) {
            return (Decimal) value;
        }
        if (value instanceof Integer) {
            return Decimal.valueOf((Integer) value);
        }
        if (value instanceof Long) {
            return Decimal.valueOf((Long) value);
        }
        return Decimal.valueOf(String.valueOf(value));
    }
}
