        return (IAccounts) Application.Domain.newInstance(records, Account.SObjectType);
    }

    public static IAccounts newInstance(Set<Id> accountIds) {
        return (IAccounts) Application.Domain.newInstance(accountIds, Account.SObjectType);
    }

    public Accounts(List<Account> records) {
        super(records);
    }

    public class Constructor implements fflib_IDomainConstructor {
        public fflib_ISObjects construct(List<SObject> sObjects) {
            return new Accounts((List<Account>) sObjects);
        }
    }

    public override Schema.SObjectType getSObjectType() {
        return Account.SObjectType;
    }

    public override Object getType() {
        return Accounts.class;
    }

    public List<Account> getAccounts() {
        return (List<Account>) getRecords();
    }

    public IAccounts selectByRating(String rating) {
        List<Account> filtered = new List<Account>();
        List<Account> accounts = getAccounts();
        if (accounts != null) {
            for (Account account : accounts) {
                if (account.Rating == rating) {
                    filtered.add(account);
                }
            }
        }
        return new Accounts(filtered);
    }

    public Set<Id> getOwnerIds() {
        Set<Id> ownerIds = new Set<Id>();
        List<Account> accounts = getAccounts();
        if (accounts != null) {
            for (Account account : accounts) {
                if (account.OwnerId != null) {
                    ownerIds.add(account.OwnerId);
                }
            }
        }
        return ownerIds;
    }

    public void setRating(String rating) {
        List<Account> accounts = getAccounts();
        if (accounts == null) {
            return;
        }
        for (Account account : accounts) {
            account.Rating = rating;
        }
    }
}
