public with sharing class AccountOnboardingService {
    public static List<Account> createAccountsWithContacts(
        Map<String, List<String>> contactLastNamesByAccountName
    ) {
        List<Account> newAccounts = new List<Account>();

        if (
            contactLastNamesByAccountName == null ||
            contactLastNamesByAccountName.isEmpty()
        ) {
            return newAccounts;
        }

        // Capture the field token before any Contact variable is in scope.
        // Naming a variable 'contact' would shadow the Contact SObject type
        // (Apex is case-insensitive) and make Contact.AccountId resolve to
        // the instance Id field instead of the Schema.SObjectField token
        // required by fflib_SObjectUnitOfWork.registerNew.
        Schema.SObjectField contactAccountIdField = Contact.AccountId;

        fflib_SObjectUnitOfWork uow = new fflib_SObjectUnitOfWork(
            new List<Schema.SObjectType>{
                Account.SObjectType,
                Contact.SObjectType
            }
        );

        for (String accountName : contactLastNamesByAccountName.keySet()) {
            Account newAccountRecord = new Account(Name = accountName);
            newAccounts.add(newAccountRecord);
            uow.registerNew(newAccountRecord);

            List<String> contactLastNames = contactLastNamesByAccountName.get(
                accountName
            );
            if (contactLastNames == null) {
                continue;
            }

            for (String contactLastName : contactLastNames) {
                Contact newContactRecord = new Contact(
                    LastName = contactLastName
                );
                uow.registerNew(
                    newContactRecord,
                    contactAccountIdField,
                    newAccountRecord
                );
            }
        }

        uow.commitWork();

        return newAccounts;
    }
}
