/**
 * @description Publishes Deal_Stage_Change__e platform events for the data warehouse.
 *
 * DEVIATION FROM THE REQUESTED IMPLEMENTATION:
 * The request asked for EventBus.publish to be called once per Opportunity
 * inside the loop. That is deliberately NOT done here. Instead, all events
 * are collected and published in a single bulk EventBus.publish(List) call.
 *
 * Reason: each EventBus.publish call counts as one DML statement against
 * the 150 DML-statement-per-transaction governor limit. This method is
 * called from a trigger handler with up to 200 Opportunities, so 200
 * individual publish calls would exceed the limit (200 > 150) and throw a
 * LimitException, aborting the whole transaction. A single bulk call
 * consumes only one DML statement regardless of the (200) events in it.
 *
 * No traceability is lost: the bulk overload returns exactly one
 * Database.SaveResult per event, in the same order as the event list
 * supplied to it. Because the event list is built in input order,
 * results[i] corresponds to opportunities[i], so the caller can still
 * identify exactly which event failed. An empty (or null) input publishes
 * nothing, consumes no publish call, and returns an empty list.
 *
 * Note: the event is defined as Publish After Commit, so a successful
 * SaveResult means the event was accepted for publication after the
 * transaction commits; it is not a guarantee of delivery to subscribers.
 */
public with sharing class DealEventPublisher {
    /**
     * @description Builds and bulk-publishes one Deal_Stage_Change__e per Opportunity.
     * @param opportunities Opportunities whose stage changes are to be published.
     * @return One Database.SaveResult per input Opportunity, in input order;
     *         an empty list if the input is null or empty.
     */
    public static List<Database.SaveResult> publishStageChanges(List<Opportunity> opportunities) {
        if (opportunities == null || opportunities.isEmpty()) {
            return new List<Database.SaveResult>();
        }

        List<Deal_Stage_Change__e> events = new List<Deal_Stage_Change__e>();
        for (Opportunity opp : opportunities) {
            events.add(
                new Deal_Stage_Change__e(
                    // String.valueOf(Id) yields the 18-character Id, matching Text(18).
                    Opportunity_Id__c = (opp == null || opp.Id == null) ? null : String.valueOf(opp.Id),
                    Stage__c = opp == null ? null : opp.StageName,
                    Amount__c = opp == null ? null : opp.Amount
                )
            );
        }

        // Single bulk publish: one DML statement, one SaveResult per event, in input order.
        return EventBus.publish(events);
    }
}
