/**
 * Creates follow-up Tasks for Opportunities.
 *
 * Deliberate deviation from the requested implementation:
 *
 * The requested one-Task-at-a-time insert inside try/catch would use one
 * DML statement per Opportunity. Apex permits at most 150 DML statements
 * per transaction, so calls containing 150-250 Opportunities would hit
 * that governor limit.
 *
 * Instead, this service constructs all Tasks and inserts them with one
 * bulk DML operation using Database.insert(tasks, false). The false
 * allOrNone argument provides the required partial-success behaviour:
 * a Task rejected by validation does not roll back the other Tasks, and
 * each Database.SaveResult identifies the corresponding failed record.
 * This therefore preserves the requested outcome while using only one
 * SOQL query and one DML statement.
 *
 * Duplicate and null Opportunity Ids are ignored so that each distinct
 * Opportunity receives one Task. An input Id for which no accessible
 * Opportunity exists is reported as failed because no Task can be
 * created for it.
 */
public with sharing class FollowUpTaskService {

    public static Set<Id> createFollowUps(List<Id> opportunityIds) {
        Set<Id> failedOpportunityIds = new Set<Id>();

        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return failedOpportunityIds;
        }

        Set<Id> uniqueOpportunityIds = new Set<Id>();
        for (Id opportunityId : opportunityIds) {
            if (opportunityId != null) {
                uniqueOpportunityIds.add(opportunityId);
            }
        }

        if (uniqueOpportunityIds.isEmpty()) {
            return failedOpportunityIds;
        }

        Map<Id, Opportunity> opportunitiesById = new Map<Id, Opportunity>([
            SELECT Id, Name, OwnerId
            FROM Opportunity
            WHERE Id IN :uniqueOpportunityIds
            WITH USER_MODE
        ]);

        for (Id opportunityId : uniqueOpportunityIds) {
            if (!opportunitiesById.containsKey(opportunityId)) {
                failedOpportunityIds.add(opportunityId);
            }
        }

        Date dueDate = Date.today().addDays(7);
        List<Task> tasksToInsert = new List<Task>();

        for (Opportunity opportunity : opportunitiesById.values()) {
            tasksToInsert.add(new Task(
                WhatId = opportunity.Id,
                OwnerId = opportunity.OwnerId,
                Subject = 'Follow up: ' + opportunity.Name,
                ActivityDate = dueDate,
                Status = 'Not Started',
                Priority = 'Normal'
            ));
        }

        if (tasksToInsert.isEmpty()) {
            return failedOpportunityIds;
        }

        List<Database.SaveResult> saveResults = Database.insert(
            tasksToInsert,
            false,
            AccessLevel.USER_MODE
        );

        for (Integer i = 0; i < saveResults.size(); i++) {
            if (!saveResults[i].isSuccess()) {
                failedOpportunityIds.add(tasksToInsert[i].WhatId);
            }
        }

        return failedOpportunityIds;
    }
}
