public with sharing class GiftImportService {

    public class WebGift {
        public String firstName;
        public String lastName;
        public String email;
        public Decimal amount;
        public Date giftDate;
    }

    public class ImportResult {
        public Boolean success;
        public Id contactId;
        public Id opportunityId;
        public String errorMessage;
    }

    public static List<ImportResult> importGifts(List<WebGift> gifts) {
        List<ImportResult> results = new List<ImportResult>();
        if (gifts == null || gifts.isEmpty()) {
            return results;
        }

        // Pre-size so results are returned in input order.
        for (Integer i = 0; i < gifts.size(); i++) {
            results.add(new ImportResult());
        }

        List<npsp__DataImport__c> dataImports = new List<npsp__DataImport__c>();
        List<Integer> dataImportGiftIndexes = new List<Integer>();

        for (Integer i = 0; i < gifts.size(); i++) {
            WebGift gift = gifts[i];
            if (gift == null) {
                results[i].success = false;
                results[i].errorMessage = 'Gift is null.';
                continue;
            }

            npsp__DataImport__c di = new npsp__DataImport__c();
            di.npsp__Contact1_Firstname__c = gift.firstName;
            di.npsp__Contact1_Lastname__c = gift.lastName;
            di.npsp__Contact1_Personal_Email__c = gift.email;
            di.npsp__Donation_Amount__c = gift.amount;
            di.npsp__Donation_Date__c = gift.giftDate;
            di.npsp__Donation_Donor__c = 'Contact1';

            dataImports.add(di);
            dataImportGiftIndexes.add(i);
        }

        if (dataImports.isEmpty()) {
            return results;
        }

        // Staged records remain in the org as the audit trail.
        insert dataImports;

        // Use the org's Data Import settings. Fill the documented defaults
        // only if the org has not configured them, so NPSP matches contacts
        // on first name, last name and email and never matches donations.
        npsp__Data_Import_Settings__c settings =
            npsp__Data_Import_Settings__c.getOrgDefaults();
        if (settings == null) {
            settings = new npsp__Data_Import_Settings__c();
        }
        if (String.isBlank(settings.npsp__Contact_Matching_Rule__c)) {
            settings.npsp__Contact_Matching_Rule__c = 'Firstname,Lastname,Email';
        }
        if (String.isBlank(settings.npsp__Donation_Matching_Behavior__c)) {
            settings.npsp__Donation_Matching_Behavior__c = 'Do Not Match';
        }

        String processError;
        try {
            // Synchronous processing in this transaction through NPSP's API.
            // NPSP marks rejected rows as Failed instead of aborting the batch.
            npsp.BDI_DataImport_API.processDataImportBatches(
                dataImports,
                settings,
                false
            );
        } catch (Exception e) {
            // Re-query below; rows already marked Imported keep their result,
            // all other rows report this/NPSP's failure information.
            processError = e.getMessage();
        }

        Set<Id> dataImportIds = new Set<Id>();
        for (npsp__DataImport__c di : dataImports) {
            dataImportIds.add(di.Id);
        }

        Map<Id, npsp__DataImport__c> processedById =
            new Map<Id, npsp__DataImport__c>([
                SELECT Id,
                       npsp__Status__c,
                       npsp__Contact1Imported__c,
                       npsp__DonationImported__c,
                       npsp__FailureInformation__c
                FROM npsp__DataImport__c
                WHERE Id IN :dataImportIds
            ]);

        for (Integer j = 0; j < dataImports.size(); j++) {
            Integer giftIndex = dataImportGiftIndexes[j];
            npsp__DataImport__c processed = processedById.get(dataImports[j].Id);
            ImportResult result = results[giftIndex];

            if (processed != null &&
                String.isNotBlank(processed.npsp__Status__c) &&
                processed.npsp__Status__c.equalsIgnoreCase('Imported')) {
                result.success = true;
                result.contactId = processed.npsp__Contact1Imported__c;
                result.opportunityId = processed.npsp__DonationImported__c;
                result.errorMessage = null;
            } else {
                result.success = false;
                result.contactId = null;
                result.opportunityId = null;
                if (processed != null &&
                    String.isNotBlank(processed.npsp__FailureInformation__c)) {
                    result.errorMessage = processed.npsp__FailureInformation__c;
                } else if (String.isNotBlank(processError)) {
                    result.errorMessage = processError;
                } else if (processed != null &&
                           String.isNotBlank(processed.npsp__Status__c)) {
                    result.errorMessage =
                        'NPSP Data Import failed with status: ' +
                        processed.npsp__Status__c;
                } else {
                    result.errorMessage = 'NPSP Data Import did not import this row.';
                }
            }
        }

        return results;
    }
}
