public with sharing class RecurringGiftService {

    public class RecurringGiftException extends Exception {}

    public class GiftRequest {
        public Id contactId;
        public Decimal amount;
        public Integer dayOfMonth;
        public Date startDate;
        public Integer installments;
        public String paymentMethod;
    }

    public static List<Id> createMonthlyGifts(List<GiftRequest> requests) {
        if (requests == null || requests.isEmpty()) {
            return new List<Id>();
        }

        Set<Id> contactIds = new Set<Id>();
        for (Integer i = 0; i < requests.size(); i++) {
            GiftRequest req = requests[i];
            if (req == null) {
                throw new RecurringGiftException('Request at index ' + i + ' is null.');
            }
            if (req.contactId == null) {
                throw new RecurringGiftException('Request at index ' + i + ': contactId is required.');
            }
            if (req.amount == null || req.amount <= 0) {
                throw new RecurringGiftException('Request at index ' + i + ': amount must be greater than zero.');
            }
            if (req.dayOfMonth == null || req.dayOfMonth < 1 || req.dayOfMonth > 31) {
                throw new RecurringGiftException('Request at index ' + i + ': dayOfMonth must be between 1 and 31.');
            }
            if (req.startDate == null) {
                throw new RecurringGiftException('Request at index ' + i + ': startDate is required.');
            }
            if (req.installments != null && req.installments < 0) {
                throw new RecurringGiftException('Request at index ' + i + ': installments cannot be negative.');
            }
            contactIds.add(req.contactId);
        }

        Map<Id, Contact> contactsById = new Map<Id, Contact>();
        for (Contact donor : [SELECT Id, AccountId FROM Contact WHERE Id IN :contactIds]) {
            contactsById.put(donor.Id, donor);
        }

        List<npe03__Recurring_Donation__c> donations = new List<npe03__Recurring_Donation__c>();
        for (GiftRequest req : requests) {
            Boolean openEnded = (req.installments == null || req.installments == 0);
            Boolean useLastDay = (req.dayOfMonth == 31);
            Contact donor = contactsById.get(req.contactId);

            npe03__Recurring_Donation__c rd = new npe03__Recurring_Donation__c();
            rd.npe03__Contact__c = req.contactId;
            if (donor != null) {
                rd.npe03__Organization__c = donor.AccountId;
            }
            rd.npe03__Amount__c = req.amount;
            rd.npe03__Installment_Period__c = 'Monthly';
            rd.npsp__InstallmentFrequency__c = 1;
            rd.npe03__Schedule_Type__c = 'Multiply By';
            rd.npe03__Date_Established__c = req.startDate;
            rd.npsp__StartDate__c = req.startDate;
            rd.npsp__Day_of_Month__c = String.valueOf(req.dayOfMonth);
            rd.npsp__Always_Use_Last_Day_Of_Month__c = useLastDay;
            rd.npsp__Status__c = 'Active';
            rd.npsp__PaymentMethod__c = req.paymentMethod;
            rd.npsp__RecurringType__c = openEnded ? 'Open' : 'Fixed';
            rd.npe03__Open_Ended_Status__c = openEnded ? 'Open' : 'None';
            if (openEnded) {
                rd.npsp__EndDate__c = null;
            } else {
                rd.npe03__Installments__c = req.installments;
                rd.npsp__EndDate__c = calculateEndDate(req);
            }
            donations.add(rd);
        }

        insert donations;

        List<Id> result = new List<Id>();
        for (npe03__Recurring_Donation__c rd : donations) {
            result.add(rd.Id);
        }
        return result;
    }

    private static Date calculateEndDate(GiftRequest req) {
        Date firstInstallment = firstInstallmentDate(req);
        if (req.installments <= 1) {
            return firstInstallment;
        }
        Integer monthIndex = (firstInstallment.year() * 12)
            + (firstInstallment.month() - 1)
            + (req.installments - 1);
        Integer endYear = monthIndex / 12;
        Integer endMonth = Math.mod(monthIndex, 12) + 1;
        return dateInMonth(endYear, endMonth, req);
    }

    private static Date firstInstallmentDate(GiftRequest req) {
        Date candidate = dateInMonth(req.startDate.year(), req.startDate.month(), req);
        if (candidate < req.startDate) {
            Date nextMonth = req.startDate.addMonths(1);
            candidate = dateInMonth(nextMonth.year(), nextMonth.month(), req);
        }
        return candidate;
    }

    private static Date dateInMonth(Integer year, Integer month, GiftRequest req) {
        Integer daysInMonth = Date.daysInMonth(year, month);
        Integer day = (req.dayOfMonth == 31) ? daysInMonth : Math.min(req.dayOfMonth, daysInMonth);
        return Date.newInstance(year, month, day);
    }
}
