/**
 * Creates NPSP Household Accounts for the event check-in flow.
 */
public with sharing class HouseholdService {

    public static Id createHousehold(List<Contact> members) {
        if (members == null || members.isEmpty()) {
            throw new IllegalArgumentException(
                'At least one household member is required.'
            );
        }

        for (Contact member : members) {
            if (member == null) {
                throw new IllegalArgumentException(
                    'Household members must not contain null contacts.'
                );
            }
        }

        Contact primaryContact = members[0];

        // Do not create the Account directly. An Account cannot be
        // inserted without its required name, and NPSP cannot name an
        // empty household because the name and greetings are derived
        // from its member contacts.
        //
        // Instead, insert the first contact on its own. In the
        // Household Account model, NPSP's contact processing creates
        // exactly one Household Account (HH_Account record type) for
        // that contact, names the household, generates its greetings,
        // and makes the contact the household's primary contact.
        insert primaryContact;

        // The NPSP-created account is assigned to the contact in the
        // database by NPSP's trigger processing, so it must be queried
        // rather than read from the in-memory contact.
        Id householdId = [
            SELECT AccountId
            FROM Contact
            WHERE Id = :primaryContact.Id
            LIMIT 1
        ].AccountId;

        if (householdId == null) {
            throw new IllegalArgumentException(
                'NPSP did not create a household account for the first contact.'
            );
        }

        // Reflect the NPSP-assigned household on the caller's contact.
        primaryContact.AccountId = householdId;

        // Insert all remaining members directly into the household
        // created for the primary contact. This prevents NPSP from
        // creating a separate household for each of them, so no extra
        // or empty household accounts are left behind, and NPSP updates
        // the household name and greetings to include all members.
        List<Contact> remainingMembers = new List<Contact>();
        for (Integer i = 1; i < members.size(); i++) {
            members[i].AccountId = householdId;
            remainingMembers.add(members[i]);
        }
        if (!remainingMembers.isEmpty()) {
            insert remainingMembers;
        }

        // Ensure the first contact in the list is recorded as the
        // household's primary contact.
        Account household = [
            SELECT Id, npe01__One2OneContact__c
            FROM Account
            WHERE Id = :householdId
            LIMIT 1
        ];
        if (household.npe01__One2OneContact__c != primaryContact.Id) {
            household.npe01__One2OneContact__c = primaryContact.Id;
            update household;
        }

        return householdId;
    }
}
